"""V62 test export: p2first detector (+ V11-family refiner) -> submission CSV shard.

Adapted from scripts/export_v21_shard.py. Changes vs that file, and ONLY these:
  * DETECTOR / REFINER paths and expected SHA-256s come from the command line (the model is a
    different checkpoint; nothing is hard-coded to V21's hashes);
  * views are generated by the shared, V17-validated `v61_toolkit.generate_views` (box iou 0.3,
    retina masks, agnostic NMS, imgsz 1024, floor 0.1, four flips) - the same function that
    produced every OOF cache this result was measured with;
  * `--no-refine` writes the direct-detector output (consensus -> pixel ownership -> confidence);
  * the v62 validator patch is NOT needed at inference (it only affects Ultralytics' validator).
Everything downstream of the views (cluster_views flip_consensus, crop_probabilities,
clean_refined_predictions mode refined_constrained, min area 20, no overlap) is identical.

It never submits. It reads only the 180 test IMAGES (no labels exist).

  CUDA_VISIBLE_DEVICES=N python scripts/export_v62_shard.py --shard-index 0 --num-shards 4 \
      --detector <final.pt> --detector-sha <sha256> --refiner <refiner.pt> --refiner-sha <sha256> \
      --mask-threshold 0.45 --confidence 0.30 --output-dir outputs/v62_export
"""
from __future__ import annotations

import argparse
import hashlib
import json
import sys
import time
from pathlib import Path

import numpy as np
import pandas as pd
from pycocotools import mask as mask_utils

SCRIPTS = Path(__file__).resolve().parent
sys.path.insert(0, str(SCRIPTS))
import reproduce_v17_from_cache as v50  # noqa: E402
import v61_toolkit as K  # noqa: E402

ROOT = SCRIPTS.parent
TEST_DIR = v50.DATA_ROOT / "test/test_images"
MIN_AREA = 20


def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def main():
    import cv2
    import torch
    from ultralytics import YOLO

    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--shard-index", type=int, required=True)
    ap.add_argument("--num-shards", type=int, default=4)
    ap.add_argument("--detector", type=Path, required=True)
    ap.add_argument("--detector-sha", required=True)
    ap.add_argument("--refiner", type=Path, default=None)
    ap.add_argument("--refiner-sha", default=None)
    ap.add_argument("--no-refine", action="store_true")
    ap.add_argument("--mask-threshold", type=float, default=0.45)
    ap.add_argument("--confidence", type=float, default=0.30)
    ap.add_argument("--output-dir", type=Path, required=True)
    args = ap.parse_args()
    if not 0 <= args.shard_index < args.num_shards:
        raise SystemExit("invalid shard index")
    if sha256(args.detector) != args.detector_sha:
        raise RuntimeError("detector checkpoint identity changed")
    model = None
    rt = None
    if not args.no_refine:
        if args.refiner is None or args.refiner_sha is None:
            raise SystemExit("--refiner and --refiner-sha are required unless --no-refine")
        if sha256(args.refiner) != args.refiner_sha:
            raise RuntimeError("refiner checkpoint identity changed")
        rt = v50.runtime_state()
        base = rt["base"]
        model = base.CropUNet(pretrained=False).to("cuda:0")
        model.load_state_dict(torch.load(args.refiner, map_location="cuda:0", weights_only=True))
        model.eval()
    core = rt["core"] if rt else None
    tta = rt["tta"] if rt else None

    detector = YOLO(str(args.detector))
    all_images = sorted(TEST_DIR.glob("*.jpeg"))
    if len(all_images) != 180:
        raise RuntimeError(f"expected 180 test images, found {len(all_images)}")
    selected = [p for i, p in enumerate(all_images) if i % args.num_shards == args.shard_index]
    args.output_dir.mkdir(parents=True, exist_ok=True)
    rows, coverage, started = [], {}, time.monotonic()
    for index, path in enumerate(selected, 1):
        views = K.generate_views(detector, path, iou=0.3)
        if args.no_refine:
            rles, scores = K.cluster_views(views)
            rles, scores = K.own_pixels(rles, scores)
            preds = [r for r, s in zip(rles, scores, strict=True) if s >= args.confidence]
        else:
            proposals, pscores = tta.cluster_views(views, "flip_consensus", match_iou=0.5)
            preds = []
            if proposals:
                masks = [mask_utils.decode(r) for r in proposals]
                gray = cv2.imread(str(path), cv2.IMREAD_GRAYSCALE)
                if gray is None or gray.shape != (2048, 2048):
                    raise RuntimeError(f"invalid grayscale image {path}")
                bounds, _, probs = core.crop_probabilities(rt["base"], model, gray, masks, True)
                rles, kept = core.clean_refined_predictions(
                    masks, pscores, bounds, probs, args.mask_threshold, "refined_constrained")
                preds = [r for r, s in zip(rles, kept, strict=True) if s >= args.confidence]
        occupied = np.zeros((2048, 2048), dtype=bool)
        for number, rle in enumerate(preds, 1):
            mask = mask_utils.decode(rle).astype(bool)
            if int(mask.sum()) < MIN_AREA or np.any(occupied & mask):
                raise RuntimeError(f"invalid area/overlap for {path.name}")
            occupied |= mask
            rows.append({"filament_id": f"{path.stem}_{number}",
                         "segmentation_rle": rle["counts"].decode()})
        coverage[path.name] = len(preds)
        if index % 10 == 0 or index == len(selected):
            print(f"shard={args.shard_index}/{args.num_shards} images={index}/{len(selected)} "
                  f"rows={len(rows)} elapsed={time.monotonic() - started:.0f}s", flush=True)

    csv_path = args.output_dir / f"shard_{args.shard_index}.csv"
    pd.DataFrame(rows, columns=["filament_id", "segmentation_rle"]).to_csv(csv_path, index=False)
    manifest = {
        "status": "complete", "shard_index": args.shard_index, "num_shards": args.num_shards,
        "files": [p.name for p in selected], "rows": len(rows),
        "empty_images": [n for n, c in coverage.items() if c == 0], "coverage": coverage,
        "detector_sha256": args.detector_sha, "refiner_sha256": args.refiner_sha,
        "recipe": {"box_iou": 0.3, "detector_floor": 0.1, "views": 4, "policy": "flip_consensus",
                   "refined": not args.no_refine, "mask_threshold": args.mask_threshold,
                   "confidence": args.confidence, "min_area": MIN_AREA},
        "csv_sha256": sha256(csv_path), "seconds": time.monotonic() - started,
        "reads_labels": False}
    (args.output_dir / f"shard_{args.shard_index}.json").write_text(
        json.dumps(manifest, indent=2) + "\n")
    print(json.dumps({k: v for k, v in manifest.items() if k != "coverage"}, indent=2))


if __name__ == "__main__":
    main()
